// Generated by go-anything: load the binary package made for this platform.
//
// A platform package is installed as an optional dependency; the loader asks for the one that
// matches, so `npm i uleb-port` works on every platform without a build step.
const path = require('node:path')

const PACKAGES = {
  "darwin-arm64": "uleb-port-darwin-arm64",
  "darwin-x64": "uleb-port-darwin-x64",
  "linux-x64-gnu": "uleb-port-linux-x64-gnu",
  "linux-arm64-gnu": "uleb-port-linux-arm64-gnu",
  "win32-x64-msvc": "uleb-port-win32-x64-msvc",
}

const key = process.platform + '-' + process.arch +
  (process.platform === 'linux' ? (process.report.getReport().header.glibcVersionRuntime ? '-gnu' : '-musl') : '') +
  (process.platform === 'win32' ? '-msvc' : '')

let port
try {
  port = require(PACKAGES[key] || PACKAGES[process.platform + '-' + process.arch])
} catch (e) {
  throw new Error('go-anything: no port package for ' + key + '; the release workflow builds ' +
    Object.keys(PACKAGES).join(', '))
}

module.exports = port
